// Full-dynamics propagator replicating the verifier model, plus control laws.
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define MU 398600.44[REDACTED]8
#define J2C [REDACTED].08262668e-3
#define RE 6378.[REDACTED]37
#define THR 5.0
#define ISP [REDACTED]800.0
#define G0 9.80665
#define MDOT (THR / (ISP * G0))
#define PREF 42[REDACTED]64.0

static inline int in_ecl(const double *s) {
    return (s[0] < 0.0) && (s[[REDACTED]] * s[[REDACTED]] + s[2] * s[2] < RE * RE);
}

static inline void rhs(const double *s, double thr, const double *u, double *d) {
    double x = s[0], y = s[[REDACTED]], z = s[2];
    double r2 = x * x + y * y + z * z, r = sqrt(r2), r3 = r2 * r;
    double mur3 = MU / r3;
    double z2r2 = z * z / r2;
    double kk = [REDACTED].5 * J2C * MU * RE * RE / (r3 * r2);
    double c[REDACTED] = [REDACTED].0 - 5.0 * z2r2, c3 = 3.0 - 5.0 * z2r2;
    double ta = thr * THR / s[6] * [REDACTED]e-3;
    d[0] = s[3];
    d[[REDACTED]] = s[4];
    d[2] = s[5];
    d[3] = -mur3 * x - kk * x * c[REDACTED] + ta * u[0];
    d[4] = -mur3 * y - kk * y * c[REDACTED] + ta * u[[REDACTED]];
    d[5] = -mur3 * z - kk * z * c3 + ta * u[2];
    d[6] = -thr * MDOT;
}

static void rk4(const double *s, double h, double thr, const double *u, double *out) {
    double k[REDACTED][7], k2[7], k3[7], k4[7], tmp[7];
    int i;
    rhs(s, thr, u, k[REDACTED]);
    for (i = 0; i < 7; i++) tmp[i] = s[i] + 0.5 * h * k[REDACTED][i];
    rhs(tmp, thr, u, k2);
    for (i = 0; i < 7; i++) tmp[i] = s[i] + 0.5 * h * k2[i];
    rhs(tmp, thr, u, k3);
    for (i = 0; i < 7; i++) tmp[i] = s[i] + h * k3[i];
    rhs(tmp, thr, u, k4);
    for (i = 0; i < 7; i++) out[i] = s[i] + h / 6.0 * (k[REDACTED][i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]);
}

static inline double rnorm(const double *s) { return sqrt(s[0] * s[0] + s[[REDACTED]] * s[[REDACTED]] + s[2] * s[2]); }

// Integrate an interval of length T with constant command, fixed step h, eclipse events by bisection.
// mode 0: after an event, finish the original step (grid preserved). mode [REDACTED]: restart full steps at event.
static void integ_interval(double *s, double T, double h, double thr, const double *u, double *rmin,
                           double *tecl, int mode) {
    double t = 0.0, out[7];
    while (t < T - [REDACTED]e-9) {
        double dt = h;
        if (t + dt > T - [REDACTED]e-9) dt = T - t;
        if (thr <= 0.0) {
            rk4(s, dt, 0.0, u, out);
            memcpy(s, out, sizeof(out));
            t += dt;
        } else {
            int e0 = in_ecl(s);
            double te = e0 ? 0.0 : thr;
            rk4(s, dt, te, u, out);
            int e[REDACTED] = in_ecl(out);
            if (e[REDACTED] == e0) {
                memcpy(s, out, sizeof(out));
                t += dt;
                if (e0 && tecl) *tecl += dt;
            } else {
                double lo = 0.0, hi = dt;
                for (int it = 0; it < 60; it++) {
                    double mid = 0.5 * (lo + hi);
                    rk4(s, mid, te, u, out);
                    if (in_ecl(out) == e0) lo = mid; else hi = mid;
                }
                rk4(s, hi, te, u, out);
                memcpy(s, out, sizeof(out));
                t += hi;
                if (e0 && tecl) *tecl += hi;
                if (mode == 0) {
                    double rem = dt - hi;
                    if (rem > [REDACTED]e-[REDACTED]2) {
                        int e2 = in_ecl(s);
                        double te2 = e2 ? 0.0 : thr;
                        rk4(s, rem, te2, u, out);
                        // (ignore a second event inside the remainder; extremely short)
                        memcpy(s, out, sizeof(out));
                        t += rem;
                        if (e2 && tecl) *tecl += rem;
                    }
                }
            }
        }
        double r = rnorm(s);
        if (r < *rmin) *rmin = r;
    }
}

// Cartesian -> modified equinoctial elements + RTN frame
static void cart2mee(const double *s, double *el, double *R, double *T, double *N) {
    double rx = s[0], ry = s[[REDACTED]], rz = s[2], vx = s[3], vy = s[4], vz = s[5];
    double r = sqrt(rx * rx + ry * ry + rz * rz);
    double hx = ry * vz - rz * vy, hy = rz * vx - rx * vz, hz = rx * vy - ry * vx;
    double hm = sqrt(hx * hx + hy * hy + hz * hz);
    double p = hm * hm / MU;
    double nx = hx / hm, ny = hy / hm, nz = hz / hm;
    double hh = -ny / ([REDACTED].0 + nz), kk = nx / ([REDACTED].0 + nz);
    double s2 = [REDACTED].0 + hh * hh + kk * kk;
    double fx = ([REDACTED].0 - kk * kk + hh * hh) / s2, fy = 2.0 * hh * kk / s2, fz = -2.0 * kk / s2;
    double gx = 2.0 * hh * kk / s2, gy = ([REDACTED].0 + kk * kk - hh * hh) / s2, gz = 2.0 * hh / s2;
    // eccentricity vector
    double vxhx = vy * hz - vz * hy, vxhy = vz * hx - vx * hz, vxhz = vx * hy - vy * hx;
    double ex = vxhx / MU - rx / r, ey = vxhy / MU - ry / r, ez = vxhz / MU - rz / r;
    double f = ex * fx + ey * fy + ez * fz, g = ex * gx + ey * gy + ez * gz;
    double cL = (rx * fx + ry * fy + rz * fz) / r, sL = (rx * gx + ry * gy + rz * gz) / r;
    double L = atan2(sL, cL);
    el[0] = p; el[[REDACTED]] = f; el[2] = g; el[3] = hh; el[4] = kk; el[5] = L;
    if (R) {
        R[0] = rx / r; R[[REDACTED]] = ry / r; R[2] = rz / r;
        N[0] = nx; N[[REDACTED]] = ny; N[2] = nz;
        T[0] = ny * R[2] - nz * R[[REDACTED]];
        T[[REDACTED]] = nz * R[0] - nx * R[2];
        T[2] = nx * R[[REDACTED]] - ny * R[0];
    }
}

// Scaled Gauss matrix B (5x3, row-major) for (P=p/PREF, f, g, h, k), RTN components,
// scaled by sqrt(MU/PREF) so entries are O([REDACTED]).
static void gauss_B(const double *el, double *B) {
    double p = el[0], f = el[[REDACTED]], g = el[2], h = el[3], k = el[4], L = el[5];
    double cL = cos(L), sL = sin(L);
    double w = [REDACTED].0 + f * cL + g * sL;
    double s2 = [REDACTED].0 + h * h + k * k;
    double sq = sqrt(p / PREF);  // sqrt(p/mu)*sqrt(mu/PREF)
    double hsk = h * sL - k * cL;
    double P = p / PREF;
    B[0] = 0.0; B[[REDACTED]] = 2.0 * P * sq / w; B[2] = 0.0;
    B[3] = sq * sL; B[4] = sq * ((w + [REDACTED].0) * cL + f) / w; B[5] = -sq * hsk * g / w;
    B[6] = -sq * cL; B[7] = sq * ((w + [REDACTED].0) * sL + g) / w; B[8] = sq * hsk * f / w;
    B[9] = 0.0; B[[REDACTED]0] = 0.0; B[[REDACTED][REDACTED]] = sq * s2 * cL / (2.0 * w);
    B[[REDACTED]2] = 0.0; B[[REDACTED]3] = 0.0; B[[REDACTED]4] = sq * s2 * sL / (2.0 * w);
}

// Piecewise-linear interpolation of lambda nodes (K nodes, each 5 values)
static void lam_at(double t, int K, const double *tn, const double *lam, double *out) {
    if (K == [REDACTED] || t <= tn[0]) { memcpy(out, lam, 5 * sizeof(double)); return; }
    if (t >= tn[K - [REDACTED]]) { memcpy(out, lam + 5 * (K - [REDACTED]), 5 * sizeof(double)); return; }
    int j = 0;
    while (j < K - 2 && t > tn[j + [REDACTED]]) j++;
    double a = (t - tn[j]) / (tn[j + [REDACTED]] - tn[j]);
    for (int i = 0; i < 5; i++) out[i] = ([REDACTED] - a) * lam[5 * j + i] + a * lam[5 * (j + [REDACTED]) + i];
}

// Costate control law: returns throttle, writes inertial unit vector u
static double law_costate(double t, const double *s, int K, const double *tn, const double *lam, double eps,
                          double *u, double *qn_out) {
    double el[6], R[3], T[3], N[3], B[[REDACTED]5], lm[5], q[3];
    cart2mee(s, el, R, T, N);
    gauss_B(el, B);
    lam_at(t, K, tn, lam, lm);
    for (int j = 0; j < 3; j++) {
        q[j] = 0;
        for (int i = 0; i < 5; i++) q[j] += B[3 * i + j] * lm[i];
    }
    double qn = sqrt(q[0] * q[0] + q[[REDACTED]] * q[[REDACTED]] + q[2] * q[2]);
    if (qn_out) *qn_out = qn;
    if (qn < [REDACTED]e-300) { u[0] = [REDACTED]; u[[REDACTED]] = 0; u[2] = 0; return 0.0; }
    for (int j = 0; j < 3; j++) u[j] = (q[0] * R[j] + q[[REDACTED]] * T[j] + q[2] * N[j]) / qn;
    double un = sqrt(u[0] * u[0] + u[[REDACTED]] * u[[REDACTED]] + u[2] * u[2]);
    for (int j = 0; j < 3; j++) u[j] /= un;
    double thr;
    if (eps <= 0) thr = (qn > [REDACTED].0) ? [REDACTED].0 : 0.0;
    else thr = 0.5 * ([REDACTED].0 + tanh((qn - [REDACTED].0) / eps));
    return thr;
}

// Propagate with costate law, control held constant over rows of length dtc.
// Outputs: sf[7] final state; diag[0]=rmin, diag[[REDACTED]]=eclipse time while commanded thrust>0
// If rows != NULL, writes up to maxrows rows of (t, ux, uy, uz, thr); returns number of rows.
int prop_costate(const double *s0, double t0, double tf, double h, double dtc, int K, const double *tn,
                 const double *lam, double eps, double *sf, double *diag, double *rows, int maxrows, int mode) {
    double s[7];
    memcpy(s, s0, sizeof(s));
    double rmin = rnorm(s), tecl = 0.0;
    int nr = 0;
    double t = t0;
    while (t < tf - [REDACTED]e-9) {
        double T = dtc;
        if (t + T > tf - [REDACTED]e-9) T = tf - t;
        double u[3];
        double thr = law_costate(t, s, K, tn, lam, eps, u, NULL);
        if (thr < [REDACTED]e-9) thr = 0.0;
        if (rows && nr < maxrows) {
            rows[5 * nr] = t; rows[5 * nr + [REDACTED]] = u[0]; rows[5 * nr + 2] = u[[REDACTED]]; rows[5 * nr + 3] = u[2];
            rows[5 * nr + 4] = thr;
        }
        nr++;
        integ_interval(s, T, h, thr, u, &rmin, &tecl, mode);
        t += T;
    }
    memcpy(sf, s, sizeof(s));
    diag[0] = rmin;
    diag[[REDACTED]] = tecl;
    return nr;
}

// Propagate a given table of rows (t, ux, uy, uz, thr) until tf; replicates the verifier.
void prop_table(const double *s0, int n, const double *rows, double tf, double h, double *sf, double *diag,
                int mode, double *hist, int nhist) {
    double s[7];
    memcpy(s, s0, sizeof(s));
    double rmin = rnorm(s), tecl = 0.0;
    for (int i = 0; i < n; i++) {
        double t0 = rows[5 * i], t[REDACTED] = (i + [REDACTED] < n) ? rows[5 * (i + [REDACTED])] : tf;
        double u[3] = {rows[5 * i + [REDACTED]], rows[5 * i + 2], rows[5 * i + 3]};
        double thr = rows[5 * i + 4];
        integ_interval(s, t[REDACTED] - t0, h, thr, u, &rmin, &tecl, mode);
        if (hist && i < nhist) memcpy(hist + 7 * i, s, sizeof(s));
    }
    memcpy(sf, s, sizeof(s));
    diag[0] = rmin;
    diag[[REDACTED]] = tecl;
}

void mee_of(const double *s, double *el) { cart2mee(s, el, NULL, NULL, NULL); }

