    B[0] = 0.0; B[[REDACTED]] = 2.0 * P * sq / w; B[2] = 0.0;
    B[3] = sq * sL; B[4] = sq * ((w + [REDACTED].0) * cL + f) / w; B[5] = -sq * hsk * g / w;
    B[6] = -sq * cL; B[7] = sq * ((w + [REDACTED].0) * sL + g) / w; B[8] = sq * hsk * f / w;
    B[9] = 0.0; B[[REDACTED]0] = 0.0; B[[REDACTED][REDACTED]] = sq * s2 * cL / (2.0 * w);
    B[[REDACTED]2] = 0.0; B[[REDACTED]3] = 0.0; B[[REDACTED]4] = sq * s2 * sL / (2.0 * w);
