// Outputs: sf[7] final state; diag[0]=rmin, diag[[REDACTED]]=eclipse time while commanded thrust>0
// If rows != NULL, writes up to maxrows rows of (t, ux, uy, uz, thr); returns number of rows.
int prop_costate(const double *s0, double t0, double tf, double h, double dtc, int K, const double *tn,
                 const double *lam, double eps, double *sf, double *diag, double *rows, int maxrows, int mode) {
    double s[7];
