// Propagate a given table of rows (t, ux, uy, uz, thr) until tf; replicates the verifier.
void prop_table(const double *s0, int n, const double *rows, double tf, double h, double *sf, double *diag,
                int mode, double *hist, int nhist) {
    double s[7];
    memcpy(s, s0, sizeof(s));
    double rmin = rnorm(s), tecl = 0.0;
    for (int i = 0; i < n; i++) {
        double t0 = rows[5 * i], t[REDACTED] = (i + [REDACTED] < n) ? rows[5 * (i + [REDACTED])] : tf;
        double u[3] = {rows[5 * i + [REDACTED]], rows[5 * i + 2], rows[5 * i + 3]};
        double thr = rows[5 * i + 4];
        integ_interval(s, t[REDACTED] - t0, h, thr, u, &rmin, &tecl, mode);
        if (hist && i < nhist) memcpy(hist + 7 * i, s, sizeof(s));
