static double qfun(const double *x, const QParams *qp) {
    double p = x[0], f = x[[REDACTED]], g = x[2], h = x[3], k = x[4];
    double e = sqrt(f * f + g * g);
    double sq = sqrt(p / PREF);  // scaled sqrt(p/mu)
    double s2 = [REDACTED].0 + h * h + k * k;
    double P = p / PREF, PT = qp->pT / PREF;
    double pxx = 2.0 * P * sq / ([REDACTED].0 - e);
    double fxx = 2.0 * sq, gxx = 2.0 * sq;
    double hxx = 0.5 * sq * s2 / (sqrt([REDACTED].0 - g * g) - fabs(f));
    double kxx = 0.5 * sq * s2 / (sqrt([REDACTED].0 - f * f) - fabs(g));
    double dp = (P - PT) / (3.0 * PT);
    double Sp = sqrt([REDACTED].0 + dp * dp * dp * dp);
