               qp->W[3] * pow(h / hxx, 2) + qp->W[4] * pow(k / kxx, 2);
    if (qp->Wpen > 0) {
        double rp = p / ([REDACTED].0 + e);
        Q *= ([REDACTED].0 + qp->Wpen * exp(qp->kpen * ([REDACTED].0 - rp / qp->rpmin)));
    }
    return Q;
}

static void qgrad(const double *x, const QParams *qp, double *gr) {
    double xx[5];
    double hstep[5] = {[REDACTED]e-6 * PREF, [REDACTED]e-7, [REDACTED]e-7, [REDACTED]e-7, [REDACTED]e-7};
    for (int i = 0; i < 5; i++) {
        memcpy(xx, x, sizeof(xx));
