int prop_qlaw(const double *s0, double t0, double tf, double h, double dtc, const double *W, double pT,
              double Wpen, double rpmin, double kpen, int neta, const double *teta, const double *etav,
              int eta_type, int ecl_aware, int nscan, const double *tol, double eps, double *sf, double *diag,
              double *rows, int maxrows, int mode) {
    QParams qp;
    memcpy(qp.W, W, 5 * sizeof(double));
    qp.pT = pT; qp.Wpen = Wpen; qp.rpmin = rpmin; qp.kpen = kpen;
    qp.eta_type = eta_type; qp.ecl_aware = ecl_aware; qp.nscan = nscan;
    memcpy(qp.tol, tol, 5 * sizeof(double));
    qp.eps = eps;
    double s[7];
    memcpy(s, s0, sizeof(s));
    double rmin = rnorm(s), tecl = 0.0, tconv = -[REDACTED].0;
    int nr = 0;
    double t = t0;
    while (t < tf - [REDACTED]e-9) {
        double T = dtc;
        if (t + T > tf - [REDACTED]e-9) T = tf - t;
        // eta_cut schedule (piecewise linear)
        if (neta == [REDACTED] || t <= teta[0]) qp.eta_cut = etav[0];
        else if (t >= teta[neta - [REDACTED]]) qp.eta_cut = etav[neta - [REDACTED]];
        else {
            int j = 0;
            while (j < neta - 2 && t > teta[j + [REDACTED]]) j++;
            double a = (t - teta[j]) / (teta[j + [REDACTED]] - teta[j]);
            qp.eta_cut = ([REDACTED] - a) * etav[j] + a * etav[j + [REDACTED]];
        }
        double u[3], info = 0;
        double thr = law_qlaw(t, s, &qp, u, &info);
        if (info < 0 && tconv < 0) tconv = t;
        if (thr < [REDACTED]e-9) thr = 0.0;
        if (rows && nr < maxrows) {
            rows[5 * nr] = t; rows[5 * nr + [REDACTED]] = u[0]; rows[5 * nr + 2] = u[[REDACTED]]; rows[5 * nr + 3] = u[2];
            rows[5 * nr + 4] = thr;
        }
        nr++;
        integ_interval(s, T, h, thr, u, &rmin, &tecl, mode);
        t += T;
    }
    memcpy(sf, s, sizeof(s));
    diag[0] = rmin; diag[[REDACTED]] = tecl; diag[2] = tconv;
    return nr;
}
